-- 105: Mirabilandia from Carter's RCDB screenshots, 2026-10-31.
-- Filled: both Desmo Race tracks (Maurer Spike Racer, same figures), Divertical,
-- Gold Digger, iSpeed, Katun, Master Thai (P&B Double Coaster Nitro; RCDB has
-- 0 inversions only), Rexplorer (S.D.C. powered).
-- Renamed: Leprotto Express -> PAW Patrol To The Rescue (2025 Nickelodeon Land),
-- then filled (L&T Junior Coaster 30x14).
-- New: Cowabunga Carts (Zierer Force, 17 Apr 2025), and removed: Family
-- Adventure (Vekoma Junior, 2001-2011), Il Bruco Magico (Big Apple, 1998-2000),
-- Katapult (Schwarzkopf, 2006 only), Sierra Tonante (S.D.C. wood, 1992-2007).
-- Relocation linked: Family Adventure -> Western Expressen (Tusenfryd, home).
-- Not linked: Katapult's other stops (Luneur Park, Marah Land) aren't parks here.
-- New model names: "Maurer Spike", "Preston & Barbieri Double Coaster",
-- "L&T Junior Coaster". Safe to run twice.
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 10, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv', 'dur', 'yr', 'opened', 'openedPrec'), 'via', '105') FROM coasters WHERE name = 'Desmo Race (Destra)' AND park = 'Mirabilandia' AND l IS NULL;
UPDATE coasters SET manu = 'Maurer Rides', model = 'Maurer Spike', h = 72.2, s = 49.7, l = 1722.4, inv = 0, dur = 60, yr = 2019, opened = '2019-07-25', openedPrec = 'day' WHERE name = 'Desmo Race (Destra)' AND park = 'Mirabilandia' AND l IS NULL;
